// ============================================================================
// 2. Extreme Floating-Point Values & Kinematics
// ============================================================================

#[test]
fn challenge_coordinates_exact_poles_and_antimeridian() {
    let mut payload = vec![0u8; MIN_OSD_PAYLOAD_LEN];

    // North Pole (+90° = +pi/2 rad), Prime Meridian (0°)
    // Note: (0,0) is uninitialized in DJI, but lat=90, lon=0 has non-zero lat
    LittleEndian::write_f64(&mut payload[0..8], 0.0); // lon
    LittleEndian::write_f64(&mut payload[8..16], std::f64::consts::FRAC_PI_2); // lat = +pi/2
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!((osd.latitude_deg - 90.0).abs() < 1e-6);
    assert_eq!(osd.latitude_1e7(), 900_000_000);
    assert_eq!(osd.longitude_1e7(), 0);
    assert!(osd.is_valid_coordinates(), "Poles must be valid coordinates");

    // South Pole (-90° = -pi/2 rad), Antimeridian (+180° = +pi rad)
    LittleEndian::write_f64(&mut payload[0..8], std::f64::consts::PI); // lon = +pi
    LittleEndian::write_f64(&mut payload[8..16], -std::f64::consts::FRAC_PI_2); // lat = -pi/2
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!((osd.latitude_deg - (-90.0)).abs() < 1e-6);
    assert!((osd.longitude_deg - 180.0).abs() < 1e-6);
    assert_eq!(osd.latitude_1e7(), -900_000_000);
    assert_eq!(osd.longitude_1e7(), 1_800_000_000);
    assert!(osd.is_valid_coordinates());

    // Western Antimeridian (-180° = -pi rad)
    LittleEndian::write_f64(&mut payload[0..8], -std::f64::consts::PI);
    LittleEndian::write_f64(&mut payload[8..16], 0.0);
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!((osd.longitude_deg - (-180.0)).abs() < 1e-6);
    assert_eq!(osd.longitude_1e7(), -1_800_000_000);
    assert!(osd.is_valid_coordinates());

    // Exact Zero Coordinates (0.0, 0.0) -> DJI convention: uninitialized GPS fix
    LittleEndian::write_f64(&mut payload[0..8], 0.0);
    LittleEndian::write_f64(&mut payload[8..16], 0.0);
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!(!osd.is_valid_coordinates(), "0,0 must be invalid");

    // Out of bounds latitude (> 90°)
    LittleEndian::write_f64(&mut payload[0..8], 0.5);
    LittleEndian::write_f64(&mut payload[8..16], 1.6); // ~91.67°
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!(!osd.is_valid_coordinates(), ">90° lat must be invalid");

    // Out of bounds longitude (> 180°)
    LittleEndian::write_f64(&mut payload[0..8], 3.2); // ~183.3°
    LittleEndian::write_f64(&mut payload[8..16], 0.5);
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!(!osd.is_valid_coordinates(), ">180° lon must be invalid");
}

#[test]
fn challenge_coordinates_pathological_floats_nan_inf() {
    let mut payload = vec![0u8; MIN_OSD_PAYLOAD_LEN];

    // NaN coordinates
    LittleEndian::write_f64(&mut payload[0..8], f64::NAN);
    LittleEndian::write_f64(&mut payload[8..16], f64::NAN);
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!(!osd.is_valid_coordinates(), "NaN must be invalid coordinates");
    // In Rust 1.45+, float-to-int cast of NaN saturates to 0 without panicking
    assert_eq!(osd.latitude_1e7(), 0);
    assert_eq!(osd.longitude_1e7(), 0);

    // +Infinity coordinates
    LittleEndian::write_f64(&mut payload[0..8], f64::INFINITY);
    LittleEndian::write_f64(&mut payload[8..16], f64::INFINITY);
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!(!osd.is_valid_coordinates(), "Infinity must be invalid");
    // Saturates to i32::MAX without panicking
    assert_eq!(osd.latitude_1e7(), i32::MAX);
    assert_eq!(osd.longitude_1e7(), i32::MAX);

    // -Infinity coordinates
    LittleEndian::write_f64(&mut payload[0..8], f64::NEG_INFINITY);
    LittleEndian::write_f64(&mut payload[8..16], f64::NEG_INFINITY);
    let osd = OsdRecord::parse(&payload).unwrap();
    assert!(!osd.is_valid_coordinates());
    assert_eq!(osd.latitude_1e7(), i32::MIN);
    assert_eq!(osd.longitude_1e7(), i32::MIN);
}

#[test]
fn challenge_supersonic_velocities_and_hypot_overflow_resistance() {
    let mut payload = vec![0u8; MIN_OSD_PAYLOAD_LEN];

    // Set maximum positive raw speeds (32767 -> 3276.7 m/s ≈ Mach 9.6)
    LittleEndian::write_i16(&mut payload[18..20], i16::MAX); // x_speed
    LittleEndian::write_i16(&mut payload[20..22], i16::MAX); // y_speed
    LittleEndian::write_i16(&mut payload[22..24], i16::MAX); // z_speed

    let osd = OsdRecord::parse(&payload).unwrap();
    let expected_xy = 3276.7 * std::f64::consts::SQRT_2; // ~4633.95 m/s
    let expected_3d = 3276.7 * 3.0f64.sqrt(); // ~5675.41 m/s

    assert!((osd.horizontal_speed() - expected_xy).abs() < 1e-2);
    assert!((osd.speed_3d() - expected_3d).abs() < 1e-2);
    assert!((osd.climb_rate() - (-3276.7)).abs() < 1e-2);

    // Set maximum negative raw speeds (-32768 -> -3276.8 m/s)
    LittleEndian::write_i16(&mut payload[18..20], i16::MIN);
    LittleEndian::write_i16(&mut payload[20..22], i16::MIN);
    LittleEndian::write_i16(&mut payload[22..24], i16::MIN);

    let osd_neg = OsdRecord::parse(&payload).unwrap();
    let expected_xy_neg = 3276.8 * std::f64::consts::SQRT_2;
    let expected_3d_neg = 3276.8 * 3.0f64.sqrt();

    assert!((osd_neg.horizontal_speed() - expected_xy_neg).abs() < 1e-2);
    assert!((osd_neg.speed_3d() - expected_3d_neg).abs() < 1e-2);
    assert!((osd_neg.climb_rate() - 3276.8).abs() < 1e-2);
}

#[test]
fn challenge_gimbal_yaw_normalization_boundary_anomaly() {
    let mut payload = vec![0u8; GIMBAL_MIN_PAYLOAD_LEN];

    // Standard negative yaw (-45.0°) -> 315.0°
    LittleEndian::write_i16(&mut payload[4..6], -450);
    let g1 = GimbalRecord::parse(&payload).unwrap();
    assert!((g1.yaw_360() - 315.0).abs() < 1e-4);

    // Zero yaw (0.0°) -> 0.0°
    LittleEndian::write_i16(&mut payload[4..6], 0);
    let g2 = GimbalRecord::parse(&payload).unwrap();
    assert!((g2.yaw_360() - 0.0).abs() < 1e-4);

    // Multi-turn negative yaw: -400.0° (raw -4000)
    // EMPIRICAL OBSERVATION: GimbalRecord::yaw_360() uses a single addition `+ 360.0`,
    // returning -40.0° instead of standard interval [0, 360) (320.0°)!
    LittleEndian::write_i16(&mut payload[4..6], -4000);
    let g3 = GimbalRecord::parse(&payload).unwrap();
    let yaw_res = g3.yaw_360();
    // Document exact behavior
    assert_eq!(yaw_res, -40.0, "GimbalRecord::yaw_360 adds 360 only once without modulo");

    // Boundary 360.0° (raw 3600)
    // EMPIRICAL OBSERVATION: yaw_360() returns 360.0 instead of 0.0
    LittleEndian::write_i16(&mut payload[4..6], 3600);
    let g4 = GimbalRecord::parse(&payload).unwrap();
    assert_eq!(g4.yaw_360(), 360.0, "GimbalRecord::yaw_360 does not wrap 360.0 to 0.0");
}

#[test]
fn challenge_rc_stick_deflection_extremes_and_saturation() {
    // Test neutral
    assert_eq!(normalize_stick(STICK_CENTER), 0.0);
    assert_eq!(stick_percent(STICK_CENTER), 0);
    assert!(!is_stick_saturated(STICK_CENTER));

    // Test disconnected (raw = 0)
    assert_eq!(normalize_stick(0), 0.0);
    assert_eq!(normalize_stick_clamped(0), 0.0);
    assert_eq!(stick_percent(0), 0);
    assert!(!is_stick_saturated(0));

    // Test endpoints
    assert_eq!(normalize_stick(STICK_MIN), -1.0);
    assert_eq!(stick_percent(STICK_MIN), -100);
    assert!(is_stick_saturated(STICK_MIN));

    assert_eq!(normalize_stick(STICK_MAX), 1.0);
    assert_eq!(stick_percent(STICK_MAX), 100);
    assert!(is_stick_saturated(STICK_MAX));

    // Deflections just beyond boundaries
    assert!(is_stick_saturated(STICK_MIN - 1));
    assert!(is_stick_saturated(STICK_MAX + 1));

    // Extreme raw: i16::MAX (32767)
    let norm_max = normalize_stick(i16::MAX);
    assert!(norm_max > 40.0);
    assert_eq!(normalize_stick_clamped(i16::MAX), 1.0);
    // EMPIRICAL OBSERVATION: stick_percent does not clamp before casting,
    // so in Rust float-to-int cast, 4810.0 saturates to i8::MAX (127)
    let pct_max = stick_percent(i16::MAX);
    assert_eq!(pct_max, 127, "Extrapolated stick_percent saturates at i8::MAX");

    // Extreme raw: i16::MIN (-32768)
    let norm_min = normalize_stick(i16::MIN);
    assert!(norm_min < -40.0);
    assert_eq!(normalize_stick_clamped(i16::MIN), -1.0);
    let pct_min = stick_percent(i16::MIN);
    assert_eq!(pct_min, -128, "Extrapolated stick_percent saturates at i8::MIN");
}

// ============================================================================
// 3. Active-Low Failsafe Invariant Under Inverted Bit Patterns
// ============================================================================

#[test]
fn challenge_active_low_failsafe_comprehensive_bit_inversions() {
    // Bit 7 is Return-To-Home failsafe alarm.
    // Active when (raw & (1 << 7)) == 0.

    // 1. Test every single-bit active mask (1 << i) for i in 0..32
    for bit in 0..32 {
        let raw = 1u32 << bit;
        let status = OsdFlightStatus::new(raw);
        if bit == 7 {
            // Bit 7 is 1 -> Failsafe is INACTIVE
            assert!(!status.is_failsafe_active(), "Bit 7 set must be INACTIVE failsafe");
        } else {
            // Bit 7 is 0 -> Failsafe is ACTIVE
            assert!(status.is_failsafe_active(), "Bit 7 clear must be ACTIVE failsafe");
        }
    }

    // 2. Test inverted single-bit masks: !(1 << i) for i in 0..32
    for bit in 0..32 {
        let raw = !(1u32 << bit);
        let status = OsdFlightStatus::new(raw);
        if bit == 7 {
            // Bit 7 is 0, all other 31 bits are 1 -> Failsafe is ACTIVE
            assert!(status.is_failsafe_active(), "Bit 7 inverted to 0 must be ACTIVE failsafe");
        } else {
            // Bit 7 is 1, bit `bit` is 0 -> Failsafe is INACTIVE
            assert!(!status.is_failsafe_active(), "Bit 7 left 1 must be INACTIVE failsafe");
        }
    }

    // 3. Canonical test vectors
    assert!(OsdFlightStatus::new(0x0000_0000).is_failsafe_active());
    assert!(!OsdFlightStatus::new(0x0000_0080).is_failsafe_active());
    assert!(!OsdFlightStatus::new(0xFFFF_FFFF).is_failsafe_active());
    assert!(OsdFlightStatus::new(0xFFFF_FF7F).is_failsafe_active());

    // 4. Checkerboard bit patterns
    // 0x5555_5555 has bit 7 == 0 (byte 0 is 0x55 = 0b0101_0101)
    assert!(OsdFlightStatus::new(0x5555_5555).is_failsafe_active());
    // 0xAAAA_AAAA has bit 7 == 1 (byte 0 is 0xAA = 0b1010_1010)
    assert!(!OsdFlightStatus::new(0xAAAA_AAAA).is_failsafe_active());
}

// ============================================================================
// 4. Battery Variant A vs B Boundary Transitions & Missing Cells
// ============================================================================

#[test]
fn challenge_battery_variant_boundary_transitions_32_33_34_35() {
    // Test Length 32: Unambiguously Variant A (Energy Summary)
    let p32 = vec![0x5Au8; 32];
    match BatteryRecord::parse(&p32).expect("Must parse len 32") {
        BatteryRecord::EnergySummary(_) => {} // Expected
        BatteryRecord::CellVoltages(_) => panic!("Length 32 must not parse as CellVoltages"),
    }

    // Test Length 33:
    // EMPIRICAL OBSERVATION & CODE DRIFT:
    // BatteryCellVoltages::parse has logic for `num32 = -1 if payload.len() == 33`,
    // BUT VARIANT_B_MIN_LEN is 34.
    // Therefore, length 33 is routed to BatteryEnergySummary!
    let p33 = vec![0x5Au8; 33];
    match BatteryRecord::parse(&p33).expect("Must parse len 33") {
        BatteryRecord::EnergySummary(_) => {} // Handled as EnergySummary
        BatteryRecord::CellVoltages(_) => panic!("Length 33 was parsed as CellVoltages"),
    }
    // Direct call to BatteryCellVoltages on length 33 fails with TruncatedRecord:
    assert!(BatteryCellVoltages::parse(&p33).is_err());

    // Test Length 34: Boundary transition to Variant B (num32 = 0)
    let mut p34 = vec![0u8; 34];
    p34[0] = 85; // SOC = 85%
    LittleEndian::write_u16(&mut p34[1..3], 15200); // 15.2V
    // Populate cell 1 and cell 2
    LittleEndian::write_u16(&mut p34[3..5], 3800); // cell 1: 3.80V
    LittleEndian::write_u16(&mut p34[5..7], 3810); // cell 2: 3.81V
    p34[31] = 2; // cell_count = 2 (at offset 31 + num32 = 31)
    LittleEndian::write_i16(&mut p34[32..34], celsius_to_deci_kelvin(25.0));

    match BatteryRecord::parse(&p34).expect("Must parse len 34") {
        BatteryRecord::CellVoltages(b) => {
            assert_eq!(b.num32, 0);
            assert_eq!(b.cell_count, 2);
            assert_eq!(b.relative_capacity, 85);
            assert!((b.voltage - 15.2).abs() < 1e-3);
            assert_eq!(b.cell_voltage(1), Some(3.800));
            assert_eq!(b.cell_voltage(2), Some(3.810));
            assert_eq!(b.cell_voltage(3), None); // missing cell
            assert!((b.temperature_celsius - 25.0).abs() < 0.2);
        }
        BatteryRecord::EnergySummary(_) => panic!("Length 34 must parse as CellVoltages"),
    }

    // Test Length 35: Variant B with prefix (num32 = 1)
    let mut p35 = vec![0u8; 35];
    p35[0] = 90;
    LittleEndian::write_u16(&mut p35[1..3], 15400);
    // Offset for cell 1 is 3 + num32 = 3 + 1 = 4
    LittleEndian::write_u16(&mut p35[4..6], 3850); // cell 1: 3.85V
    LittleEndian::write_u16(&mut p35[6..8], 3860); // cell 2: 3.86V
    p35[32] = 2; // cell_count at offset 31 + 1 = 32
    LittleEndian::write_i16(&mut p35[33..35], celsius_to_deci_kelvin(28.5)); // temp at 32 + 1 = 33

    match BatteryRecord::parse(&p35).expect("Must parse len 35") {
        BatteryRecord::CellVoltages(b) => {
            assert_eq!(b.num32, 1);
            assert_eq!(b.cell_count, 2);
            assert_eq!(b.relative_capacity, 90);
            assert_eq!(b.cell_voltage(1), Some(3.850));
            assert_eq!(b.cell_voltage(2), Some(3.860));
            assert_eq!(b.cell_voltage(3), None);
            assert!((b.temperature_celsius - 28.5).abs() < 0.2);
        }
        BatteryRecord::EnergySummary(_) => panic!("Length 35 must parse as CellVoltages"),
    }
}

#[test]
fn challenge_battery_missing_cell_sentinels_and_statistics() {
    let mut p = vec![0u8; 34];
    p[0] = 50;
    LittleEndian::write_u16(&mut p[1..3], 12000);
    p[31] = 4; // cell_count = 4

    // Cell 1: 3.800V
    LittleEndian::write_u16(&mut p[3..5], 3800);
    // Cell 2: 0 mV (unconnected / bad reading) -> Must become sentinel
    LittleEndian::write_u16(&mut p[5..7], 0);
    // Cell 3: 3.820V
    LittleEndian::write_u16(&mut p[7..9], 3820);
    // Cell 4: 0xFFFF (unconnected / missing slot) -> Must become sentinel
    LittleEndian::write_u16(&mut p[9..11], 0xFFFF);

    let b = BatteryCellVoltages::parse(&p).unwrap();
    assert_eq!(b.cell_voltage(1), Some(3.800));
    assert_eq!(b.cell_voltage(2), None, "0 mV cell must be sentinel");
    assert_eq!(b.cell_voltage(3), Some(3.820));
    assert_eq!(b.cell_voltage(4), None, "0xFFFF cell must be sentinel");
    assert_eq!(b.cell_voltage(5), None, "Cell > cell_count must be sentinel");

    // Statistics should ignore sentinels
    assert_eq!(b.max_cell_voltage(), Some(3.820));
    assert_eq!(b.min_cell_voltage(), Some(3.800));
    let dev = b.max_cell_deviation().unwrap();
    assert!((dev - 0.020).abs() < 1e-4);

    // If cell_count is 0, stats return None
    let mut p_zero = p.clone();
    p_zero[31] = 0;
    let b_zero = BatteryCellVoltages::parse(&p_zero).unwrap();
    assert_eq!(b_zero.max_cell_voltage(), None);
    assert_eq!(b_zero.min_cell_voltage(), None);
    assert_eq!(b_zero.max_cell_deviation(), None);
}

#[test]
fn challenge_battery_current_draw_inversion_math() {
    // Discharging current above 40.0A uses 2's complement
    assert_eq!(raw_current_to_amperes(0), 0.0);
    assert_eq!(raw_current_to_amperes(15000), 15.0);
    assert_eq!(raw_current_to_amperes(40000), 40.0);
    // 41000 mA -> val = 41.0 > 40.0 -> (65536 - 41000) / 1000 = 24.536 A
    assert!((raw_current_to_amperes(41000) - 24.536).abs() < 1e-4);
    // 65535 mA -> (65536 - 65535) / 1000 = 0.001 A
    assert!((raw_current_to_amperes(65535) - 0.001).abs() < 1e-4);
}

