            let _ = osd.flight_status.mode_channel_enum();
            let _ = osd.flight_status.is_gps_used();
            let _ = osd.flight_status.battery_type_enum();
        }

        // 2. Home
        if let Ok(home) = HomeRecord::parse(&buf) {
            let _ = home.dat_file_name();
            let _ = home.latitude_1e7();
            let _ = home.longitude_1e7();
            let _ = home.is_valid_coordinates();
            let _ = home.status.is_home_record();
