            let _ = home.status.ioc_mode();
        }

        // 3. Gimbal
        if let Ok(gimbal) = GimbalRecord::parse(&buf) {
            let _ = gimbal.yaw_360();
            let _ = gimbal.is_at_any_limit();
            let _ = gimbal.mode.as_str();
        }

        // 4. RC
        if let Ok(rc) = RcRecord::parse(&buf) {
