        if let Ok(sbg) = SmartBatteryGroup::parse(&buf) {
            let _ = sbg.has_alert(smart_battery_alerts::BATTERY_CELL_ERROR);
            let _ = sbg.has_alert(smart_battery_alerts::BATTERY_DANGEROUS);
        }

        let _ = TripodStateRecord::parse(&buf);

        if let Ok(rec) = FlightRecordRecover::parse(&buf) {
            let _ = rec.aircraft_serial_str();
            let _ = rec.aircraft_name_str();
